const brut = $input.first().json;
let e = (brut.body && brut.body.edition !== undefined) ? brut.body.edition : (brut.edition !== undefined ? brut.edition : brut.body);
if (typeof e === 'string') { e = JSON.parse(e.replace(/^```(json)?/, '').replace(/```$/, '').trim()); }
if (!e || typeof e !== 'object') throw new Error('Édition absente ou illisible');
const types = ['Lancement', 'Nouvelle fonction', 'Modèle', 'Étude'];
const impacts = ['fort', 'moyen', 'faible'];
const articles = (Array.isArray(e.articles) ? e.articles : []).slice(0, 5).filter(a => a && a.url && a.titre && /^https?:\/\//.test(a.url)).map(a => ({
  id: String(a.id || ''), titre: String(a.titre), source: String(a.source || ''), url: String(a.url), date: String(a.date || ''),
  type: types.includes(a.type) ? a.type : 'Lancement', impact: impacts.includes(a.impact) ? a.impact : 'moyen',
  ce_qui_sort: String(a.ce_qui_sort || ''), pour_un_pm: String(a.pour_un_pm || '')
}));
const essentiels = (Array.isArray(e.essentiels) ? e.essentiels : []).slice(0, 3).map(String);
const titre = String(e.titre || '').replace(/\s+/g, ' ').trim().slice(0, 90);
const bilan = e.bilan || {};
const dateEdition = DateTime.now().setZone('Europe/Paris').toFormat('yyyy-LL-dd');
const propre = { date: dateEdition, titre, essentiels, articles, bilan };
return [{ json: { date_edition: dateEdition, statut: 'prete', nb_articles: articles.length, contenu: JSON.stringify(propre) } }];
